import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';
import { QUEST_POOL, type QuestConfigData } from '../Config/QuestConfig';
import { HallEvents } from '../HallEvents';

interface QuestProgress {
    config: QuestConfigData;
    current: number;
    completed: boolean;
}

export class QuestSystem implements System {
    private _world: World = null!;
    private _quests: QuestProgress[] = [];

    onStart(world: World): void {
        this._world = world;
        this._quests = QUEST_POOL.map(c => ({ config: c, current: 0, completed: false }));

        world.bus.on(HallEvents.BUILD_COMPLETED, this._onBuild, this);
        world.bus.on(HallEvents.UPGRADE_COMPLETED, this._onUpgrade, this);
        world.bus.on(HallEvents.INCOME_COLLECTED, this._onCollect, this);

        this._world.bus.emit(HallEvents.QUEST_LIST_CHANGED, this._quests);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.BUILD_COMPLETED, this._onBuild, this);
        world.bus.off(HallEvents.UPGRADE_COMPLETED, this._onUpgrade, this);
        world.bus.off(HallEvents.INCOME_COLLECTED, this._onCollect, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onBuild(building: BuildingEntity): void {
        for (const q of this._quests) {
            if (q.completed) continue;
            if (q.config.type !== 'build_count') continue;
            if (q.config.buildingTypeId && q.config.buildingTypeId !== building.typeId) continue;
            this._progress(q, 1);
        }
    }

    private _onUpgrade(): void {
        for (const q of this._quests) {
            if (q.completed) continue;
            if (q.config.type !== 'upgrade_count') continue;
            this._progress(q, 1);
        }
    }

    private _onCollect(amount: number): void {
        for (const q of this._quests) {
            if (q.completed) continue;
            if (q.config.type !== 'collect_total') continue;
            this._progress(q, amount);
        }
    }

    private _progress(q: QuestProgress, delta: number): void {
        q.current = Math.min(q.current + delta, q.config.target);
        if (q.current >= q.config.target && !q.completed) {
            q.completed = true;
            this._world.bus.emit(HallEvents.QUEST_COMPLETED, q.config);
            if (q.config.reward.coins) {
                this._world.bus.emit(HallEvents.REWARD_GRANT_REQUEST, { coins: q.config.reward.coins });
            }
        }
        this._world.bus.emit(HallEvents.QUEST_LIST_CHANGED, this._quests);
    }
}